public class UserService {
    private final UserRepository repository;

    public Optional<User> findUserById(Long id) {
        User user = repository.findById(id);
        return Optional.ofNullable(user);  // wrap potentially null result
    }

    public String getUserEmailOrDefault(Long id) {
        return findUserById(id)
            .map(User::getEmail)           // transform if present
            .orElse("no-email@example.com"); // fallback if empty
    }

    public void processUser(Long id) {
        findUserById(id)
            .ifPresent(user -> {           // execute only if present
                System.out.println("Processing: " + user.getName());
                user.setLastLogin(LocalDateTime.now());
            });
    }
}

