public class UserService {
    private final UserRepository repository;

    public Optional<String> getUserCity(Long userId) {
        return repository.findById(userId)           // returns Optional<User>
            .map(User::address)                      // User -> Address, wrapped in Optional
            .map(Address::city);                     // Address -> String, wrapped in Optional
    }

    public Optional<String> getUserCityWithFlatMap(Long userId) {
        return repository.findByIdOptional(userId)   // returns Optional<User>
            .flatMap(user -> getAddressOptional(user)) // returns Optional<Address>, flattened
            .map(Address::city);                       // simple map at the end
    }

    private Optional<Address> getAddressOptional(User user) {
        return Optional.ofNullable(user.address());
    }
}

