public class OrderService {
    // Old style with null - prone to NPE
    public String getCustomerNameOld(Long orderId) {
        Order order = repository.findById(orderId);  // might return null
        if (order != null) {
            Customer customer = order.getCustomer();  // might be null
            if (customer != null) {
                return customer.getName().toUpperCase();  // name might be null
            }
        }
        return "UNKNOWN";
    }

    // With Optional - no NPE possible
    public String getCustomerName(Long orderId) {
        return repository.findByIdOptional(orderId)  // returns Optional<Order>
            .map(Order::getCustomer)                 // Optional<Customer>, empty if no customer
            .map(Customer::getName)                  // Optional<String>, empty if no name
            .map(String::toUpperCase)                // still Optional<String>
            .orElse("UNKNOWN");                      // extract with default
    }
}
